// Writes web/wasm/defaults.js: what the pages start from (syn::models::defaults -- the levers, the theories' designs,
// the populations and the default specification), from the library itself, so no page restates it. Run by the WASM
// build (Dockerfile) after the module is built.
//   node wasm/defaults.mjs
import { writeFileSync } from 'node:fs';
import createSynModule from '../web/wasm/syn.js';

const syn = await createSynModule();
const d = syn.defaults();
if (d.error) throw new Error(d.error);
writeFileSync(new URL('../web/wasm/defaults.js', import.meta.url),
  '// Generated by wasm/defaults.mjs from the library (syn::models::defaults); do not edit.\n' +
  `export default ${JSON.stringify(d, null, 1)};\n`);
